/// <reference types="nativewind/types" />

// Not part of NativeWind's own generated file (see react-native-css's `setupTypeScript`) —
// added by hand because this TypeScript version (6.x, `"module": "preserve"`) reports a
// side-effect CSS import (`import "./global.css"` in index.ts) as an unresolvable module
// without an ambient declaration, which older TS/generator versions didn't require.
declare module "*.css"
